A = [[1, 2], [0, 3]]
A2 = [[sum(A[i][k] * A[k][j] for k in range(2)) for j in range(2)] for i in range(2)]
M = [[A2[i][j] - 4 * A[i][j] + (3 if i == j else 0) for j in range(2)] for i in range(2)]
for row in M:
    for v in row:
        print(round(float(v), 6))
det = 3
inv = [[A[1][1] / det, -A[0][1] / det], [-A[1][0] / det, A[0][0] / det]]
for row in inv:
    for v in row:
        print(round(float(v), 6))
